<?php
declare(strict_types=1);
namespace EPejabat\Core;
final class FacilityDirectory {
 public static function records():array {return json_decode(file_get_contents(APP_ROOT.'/database/reference/kelantan-facility-directory.json'),true,512,JSON_THROW_ON_ERROR)['records'];}
 public static function fullName(string $name):string {return preg_replace(['/\APKD\s+/i','/\AKK\s+/i','/\AKD\s+/i','/\AKKom\s+/i'],['Pejabat Kesihatan Daerah ','Klinik Kesihatan ','Klinik Desa ','Klinik Komuniti '],$name);}
 public static function preview(\PDO $p,int $actor):array {
  Authorization::require($p,$actor,'core.master.manage');$orgs=Database::query($p,"SELECT id,name,code,parent_id FROM organisations WHERE type='pkd' AND is_active=1")->fetchAll();$out=[];
  foreach(self::records() as $r){$parent=null;foreach($orgs as $o)if(MasterSourceImport::normalisedName($o['name'])===MasterSourceImport::normalisedName('Pejabat Kesihatan Daerah '.($r['district']??'')))$parent=$o;$r['proposed_parent_id']=$parent?(int)$parent['id']:null;$r['proposed_parent_name']=$parent?self::fullName($parent['name']):null;$r['status']=$parent?'PENDING_ADMIN_PARENT_CONFIRMATION':'HOLD_PARENT_NOT_AVAILABLE';if($parent&&!Authorization::allowed($p,$actor,'core.organisations.manage',(int)$parent['id'])){$r['status']='HOLD_SCOPE';$r['proposed_parent_id']=null;}$r['existing_id']=Database::query($p,'SELECT id FROM organisations WHERE code=?',[$r['local_code']])->fetchColumn()?:null;if($r['existing_id'])$r['status']='DUPLICATE_EXISTING';$out[]=$r;}
  return $out;
 }
 public static function fingerprint(array $rows):string {return hash('sha256',json_encode($rows,JSON_THROW_ON_ERROR));}
 public static function apply(\PDO $p,int $actor,array $districts,bool $rename,string $reason,string $hash,bool $confirmed):array {
  if(!$confirmed)throw new \RuntimeException('Admin mesti mengesahkan nama dan induk pentadbiran bagi setiap calon yang dipilih.');$reason=Core::text($reason,500);$rows=self::preview($p,$actor);if(!hash_equals(self::fingerprint($rows),$hash))throw new \RuntimeException('Preview berubah; muat semula sebelum import.');$valid=array_unique(array_filter(array_column($rows,'district')));if(count($districts)!==count(array_unique($districts))||array_diff($districts,$valid))throw new \InvalidArgumentException('Pilihan daerah tidak sah.');
  return Core::tx($p,function()use($p,$actor,$rows,$districts,$rename,$reason){$selected=[];$mapping=[];foreach($rows as $r){if(!in_array($r['district'],$districts,true))continue;if(in_array($r['status'],['HOLD_PARENT_NOT_AVAILABLE','HOLD_SCOPE'],true))throw new \RuntimeException('Induk/skop tidak tersedia. Hentikan batch.');if($r['status']==='DUPLICATE_EXISTING')continue;$parent=$r['proposed_parent_id'];MasterSourceImport::reviewOrganisationSource($p,$actor,$r['local_code'],$parent,'VERIFIED',$r['source'],$reason.' — explicit Admin administrative-parent confirmation');$selected[]=$r['local_code'];$mapping[$r['local_code']]=$parent;}
   $result=[];foreach(array_chunk($selected,100) as $chunk)$result=[...$result,...MasterSourceImport::apply($p,$actor,$chunk,$reason,$mapping)];$byCode=array_column($rows,null,'local_code');foreach($result as $entry){if($entry['status']!=='IMPORTED')continue;$r=$byCode[$entry['code']];$full=self::fullName($r['source_name']);if($full!==$r['source_name'])MasterSourceImport::organisationOfficialName($p,$actor,(int)$entry['id'],$full,$r['source'],$reason.' — Admin confirmed expanded full name');if(($r['phone_validation']??'')==='ADMIN_VERIFICATION_REQUIRED')Database::query($p,'UPDATE organisations SET phone=NULL WHERE id=?',[$entry['id']]);}
   if($rename){$o=Database::query($p,'SELECT * FROM organisations WHERE id=3 FOR UPDATE')->fetch();if(!$o||$o['type']!=='pkd'||(int)$o['parent_id']!==2||MasterSourceImport::normalisedName($o['name'])!=='pejabat kesihatan daerah kota bharu')throw new \RuntimeException('Rekod ID 3/induk Kota Bharu tidak sepadan. Batch dibatalkan.');if($o['name']!=='Pejabat Kesihatan Daerah Kota Bharu')MasterSourceImport::organisationOfficialName($p,$actor,3,'Pejabat Kesihatan Daerah Kota Bharu','https://jknkelantan.moh.gov.my/jknkelantan/v1/index.php/component/sppagebuilder/page/7',$reason);}
   Audit::record($p,'master.facility_directory_batch',$actor,null,null,'core',$reason,null,['imported'=>count(array_filter($result,fn($x)=>$x['status']==='IMPORTED')),'rename_kota_bharu'=>$rename]);return $result;
  });
 }
 public static function render(\PDO $p,int $actor):string {
  $rows=self::preview($p,$actor);$groups=[];foreach($rows as $r){$key=$r['district']??'Induk belum dikenal pasti';$groups[$key]??=['count'=>0,'selectable'=>true];$groups[$key]['count']++;if(str_starts_with($r['status'],'HOLD'))$groups[$key]['selectable']=false;}ksort($groups);$h='<section class="card"><h2>Direktori Fasiliti Kelantan — Preview &amp; Import</h2><p>'.count($rows).' calon daripada direktori rasmi. Alamat bukan bukti induk pentadbiran. Hospital/pergigian tidak dimasukkan ke PKD secara automatik. Semak semua calon sebelum memilih kumpulan.</p><div class="table-wrap"><table><thead><tr><th>Fasiliti</th><th>Cadangan induk</th><th>Status</th><th>Sumber</th></tr></thead><tbody>';foreach($rows as $r)$h.='<tr><td>'.Support::escape(self::fullName($r['source_name'])).'</td><td>'.Support::escape($r['proposed_parent_name']??'Belum dipautkan').'</td><td>'.Support::escape($r['status']).'</td><td><a href="'.Support::escape($r['source']).'" target="_blank" rel="noopener">KKM</a></td></tr>';$h.='</tbody></table></div>';$f='<input type="hidden" name="preview_hash" value="'.self::fingerprint($rows).'"><fieldset><legend>Pilih kumpulan selepas semakan</legend>';foreach($groups as $district=>$g)$f.='<label><input type="checkbox" name="districts[]" value="'.Support::escape($district).'"'.($g['selectable']?'':' disabled').'>'.Support::escape($district).' — '.$g['count'].' calon'.($g['selectable']?'':' (HOLD)').'</label>';$f.='</fieldset><label><input type="checkbox" name="rename_kota_bharu" value="1">Sahkan nama penuh Kota Bharu pada ID 3; ID/kod/parent kekal</label><label><input type="checkbox" name="confirmed" value="1" required>Saya telah menyemak dan mengesahkan nama penuh serta induk pentadbiran SEMUA calon dalam kumpulan dipilih. Lokasi alamat sahaja bukan bukti.</label><label>Sebab / rujukan semakan pentadbiran<input name="reason" required maxlength="500"></label>';$h.=Support::form('facility_batch_apply',$f,'Sahkan & import batch terpilih');return $h.'<p>Tiada import berlaku ketika preview atau extract ZIP.</p></section>';
 }
}
